import json, re, datetime
event = ''
try:
    event = str(vars.get('event', ''))
    scope = str(vars.get('scope', 'current'))
    amount_text = str(vars.get('amount_text', '')).strip()
    amount_scope = str(vars.get('amount_scope', ''))
    phrase = str(vars.get('date_phrase', '')).strip()
    security_answer = str(vars.get('security_answer', '')).strip()
    cb_time = str(vars.get('callback_time', '')).strip()
    hardship = vars.get('hardship_mentioned') == 'yes'
    initial_offer = vars.get('split_started') != 'yes'
    vars['event'] = ''
    vars['amount_text'] = ''
    vars['amount_scope'] = ''
    vars['date_phrase'] = ''
    vars['hardship_mentioned'] = 'no'
    vars['decision_route'] = 'collect'
    vars['next_instruction'] = 'Ask only for the missing or unclear payment detail.'
    vars['identity_feedback'] = ''
    vars['resolution_ready'] = 'no'
    vars['close_ready'] = 'no'
    if event != 'confirm':
        vars['confirmation_state'] = 'none'
        vars['confirmed_promises'] = []
    now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00')).replace(tzinfo=None)
    today = now.date()
    holidays = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
    def business(d):
        return d.weekday() < 5 and d.isoformat() not in holidays
    def following(d):
        while not business(d):
            d += datetime.timedelta(days=1)
        return d
    def parsed(text):
        try:
            text = text.lower().strip().replace(',', '')
            text = re.sub(r'^on\s+', '', text)
            if text == 'today':
                return today
            if text == 'tomorrow':
                return today + datetime.timedelta(days=1)
            if text in ['day after tomorrow', 'the day after tomorrow']:
                return today + datetime.timedelta(days=2)
            days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
            m = re.fullmatch(r'(this|next)\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)', text)
            if m:
                monday = today - datetime.timedelta(days=today.weekday())
                return monday + datetime.timedelta(days=days.index(m.group(2)) + (7 if m.group(1) == 'next' else 0))
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', text):
                return datetime.date.fromisoformat(text)
            clean = re.sub(r'(\d)(st|nd|rd|th)\b', r'\1', text)
            clean = re.sub(r'\b(the|of)\s+', '', clean)
            for fmt in ['%d %B %Y', '%B %d %Y', '%d %b %Y', '%b %d %Y', '%d %B', '%B %d', '%d %b', '%b %d']:
                try:
                    p = datetime.datetime.strptime(clean, fmt)
                    return datetime.date(p.year if '%Y' in fmt else today.year, p.month, p.day)
                except Exception:
                    pass
        except Exception:
            pass
        return False
    if vars.get('transfer_requested') == 'yes':
        vars['decision_route'] = 'reconcile' if vars.get('transfer_state') == 'succeeded' else 'record'
        vars['record_mode'] = 'transfer_hold'
        vars['next_instruction'] = 'The requested transfer must be resolved. Do not negotiate, record abandoned promises or write notes. Do not repeat a successful transfer. A failed transfer may be repeated on customer request after a confirmed API 500.'
    elif event == 'security':
        vars['decision_route'] = 'identity'
        vars['record_mode'] = ''
        vars['pending_facts'] = ''
        vars['security_result_state'] = 'idle'
        stage = str(vars.get('security_state', 'date_of_birth'))
        answer = ''
        if stage == 'failed':
            vars['decision_route'] = 'reconcile'
        elif stage == 'verified':
            vars['identity_feedback'] = 'Security is already complete. Do not re-ask either passed question.'
        elif stage == 'date_of_birth' and vars.get('dob_passed') != 'yes':
            month_word = bool(re.search(r'\b(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\b', security_answer.lower()))
            if vars.get('security_need_month_word') == 'yes' and not month_word:
                vars['identity_feedback'] = 'Ask the customer to say the birth month as a word. Do not submit a numeric-only retry or count an attempt.'
            else:
                clean = re.sub(r'(\d)(st|nd|rd|th)\b', r'\1', security_answer.lower().replace(',', ''))
                m = re.fullmatch(r'(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})', clean)
                try:
                    if m:
                        answer = datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1))).isoformat()
                    else:
                        for fmt in ['%Y-%m-%d', '%d %B %Y', '%B %d %Y', '%d %b %Y', '%b %d %Y']:
                            try:
                                answer = datetime.datetime.strptime(clean, fmt).date().isoformat()
                                break
                            except Exception:
                                pass
                except Exception:
                    answer = ''
                if not answer:
                    vars['identity_feedback'] = 'Ask only for the missing or ambiguous part of the birth date, including the year if missing. Use the corrected customer answer. Do not validate a partial answer or count an attempt.'
        elif stage == 'phone_last4' and vars.get('dob_passed') == 'yes' and vars.get('phone_passed') != 'yes':
            words = dict(zero='0', oh='0', one='1', two='2', three='3', four='4', five='5', six='6', seven='7', eight='8', nine='9')
            candidate = ''.join(words.get(x, x) for x in re.split(r'[\s,\-]+', security_answer.lower()))
            if re.fullmatch(r'\d{4}', candidate):
                answer = candidate
            else:
                vars['identity_feedback'] = 'Ask only for the missing or unclear phone digits, preserving the digits already supplied and leading zeroes. Do not submit fewer or more than four digits, pad an answer, or count an attempt.'
        else:
            vars['identity_feedback'] = 'Do not re-ask a passed question. Explain that complete bank verification has not yet been confirmed; disclose no account information.'
        if answer:
            vars['prepared_security_field'] = stage
            vars['prepared_security_answer'] = answer
            vars['security_result_state'] = 'awaiting'
            vars['record_mode'] = 'security'
            vars['pending_facts'] = json.dumps(dict(field=stage, answer=answer))
            vars['next_instruction'] = 'Immediately check this complete customer-supplied answer with verify_identity. Do not claim verification before its result.'
            vars['decision_route'] = 'record'
    elif event == 'callback':
        vars['decision_route'] = 'identity'
        next_day = following(today + datetime.timedelta(days=1))
        vars['callback_facts'] = json.dumps(dict(today=today.isoformat(), next_business_day=next_day.isoformat(), earliest='10:00', latest='19:00', strictly_after=str(vars.get('now', ''))))
        date_text = phrase or str(vars.get('callback_draft_phrase', ''))
        time_text = cb_time or str(vars.get('callback_draft_time', ''))
        vars['callback_draft_phrase'] = date_text
        vars['callback_draft_time'] = time_text
        d = parsed(date_text) if date_text else False
        time_match = re.fullmatch(r'(\d{2}):(\d{2})', time_text)
        t = False
        if time_match:
            try:
                t = datetime.time(int(time_match.group(1)), int(time_match.group(2)))
            except Exception:
                pass
        invalid = bool(d and d not in [today, next_day]) or bool(t and not datetime.time(10, 0) <= t <= datetime.time(19, 0)) or bool(time_match and not t)
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_text) and not d:
            invalid = True
        if d and t and datetime.datetime.combine(d, t) <= now:
            invalid = True
        if invalid:
            count = int(vars.get('callback_invalid_count', 0)) + 1
            vars['callback_invalid_count'] = count
            vars['callback_draft_phrase'] = ''
            vars['callback_draft_time'] = ''
            vars['callback_time'] = ''
            if count >= 2:
                vars['identity_exit'] = 'no_callback'
                vars['decision_route'] = 'reconcile'
            else:
                vars['identity_feedback'] = 'That time is outside the callback window. Ask once for another time: today ' + today.isoformat() + ' or ' + next_day.isoformat() + ', 10:00 through 19:00, strictly later than the call time.'
        elif not d or not t:
            vars['identity_feedback'] = 'Ask only for the missing or ambiguous callback day or time; ask for a named month if a numeric date is ambiguous. Allowed days: ' + today.isoformat() + ' and ' + next_day.isoformat() + '; 10:00–19:00, later than now. Do not schedule yet.'
        else:
            vars['callback_date_ready'] = d.isoformat()
            vars['callback_time_ready'] = t.strftime('%H:%M')
            vars['callback_state'] = 'ready'
            vars['record_mode'] = 'callback'
            vars['pending_facts'] = json.dumps(dict(date=d.isoformat(), time=t.strftime('%H:%M')))
            vars['next_instruction'] = 'Immediately schedule exactly the validated callback date and time.'
            vars['decision_route'] = 'record'
    else:
        rows = vars.get('product_state', [])
        if isinstance(rows, str):
            rows = json.loads(rows)
        if not isinstance(rows, list) or not rows or vars.get('security_state') != 'verified':
            raise ValueError('Missing verified products')
        vars['operational_hold'] = ''
        current = int(vars.get('current_index', 0))
        if not 0 <= current < len(rows):
            current = 0
        targets = [p for p in rows if p.get('state') in ['open', 'pending']] if scope == 'all' else [p for p in rows if p.get('product_id') == (rows[current]['product_id'] if scope == 'current' else scope)]
        if targets:
            current = next(i for i, p in enumerate(rows) if p['product_id'] == targets[0]['product_id'])
            vars['current_index'] = current
        messages = []
        blocked = False
        if hardship:
            vars['hardship_active'] = 'yes'
            messages.append('Give one short sentence of sympathy and offer connection to customer support. Process a voluntary payment proposal without persuasion.')
        def signature(amount, date):
            return str(float(amount)) + '|' + str(date)
        def offer(p):
            if vars.get('hardship_active') == 'yes':
                return 'Offer connection to customer support; do not persuade.'
            while int(p.get('attempts', 0)) < int(p['attempt_limit']):
                n = int(p.get('attempts', 0)) + 1
                p['attempts'] = n
                a = p['floor'] if n == 2 or p.get('full_too_much') else p['past_due']
                d = p['deadline'] if n == 2 else p['attempt1_date']
                if not d:
                    p['offer_amount'] = a
                    p['offer_date'] = ''
                    return 'The literal attempt-1 day is past and cannot be offered. Ask for an exact permissible payment day; allowed days are ' + ', '.join(p['allowed_dates']) + '.'
                if signature(a, d) in p.get('rejected', []):
                    continue
                p['offer_amount'] = a
                p['offer_date'] = d
                p['amount'] = a
                p['date'] = ''
                return 'Offer ' + p['label'] + ': ' + str(a) + ' on ' + d + '.' + (' Explain that the rest stays overdue.' if a < p['past_due'] else '')
            p['state'] = 'note'
            p['reason'] = 'refused'
            return ''
        if event == 'confirm':
            pending = [p for p in rows if p.get('state') == 'pending']
            if vars.get('confirmation_state') != 'awaiting' or not pending or any(p.get('state') == 'open' for p in rows):
                messages.append('A complete current joint read-back is required before confirmation.')
                blocked = True
            else:
                if not all(p['date'] in p['allowed_dates'] and p['floor'] <= float(p['amount']) <= p['past_due'] for p in pending):
                    raise ValueError('Invalid confirmed proposal')
                vars['confirmation_state'] = 'confirmed'
                vars['confirmed_promises'] = [dict(product_id=p['product_id'], amount=p['amount'], date=p['date']) for p in pending]
                vars['record_mode'] = 'promises'
                vars['decision_route'] = 'record'
                messages.append('Immediately call create_promise for the first still-pending confirmed product.')
        elif event == 'no_talk':
            count = int(vars.get('dont_talk_count', 0)) + 1
            vars['dont_talk_count'] = count
            if count >= 2:
                for p in rows:
                    if p.get('state') in ['open', 'pending']:
                        p['state'] = 'note'
                        p['reason'] = 'refused'
            else:
                messages.append('Acknowledge briefly that they do not want to talk. Do not treat this as a second refusal; keep the next question short.')
                blocked = True
        elif event in ['hardship', 'decline_support']:
            vars['hardship_active'] = 'yes'
            if event == 'hardship':
                if not hardship:
                    messages.append('Say one short sentence of sympathy and offer connection to customer support. Make no persuasion attempt.')
                blocked = True
            else:
                for p in rows:
                    if p.get('state') == 'open' or p.get('state') == 'pending' and not p.get('voluntary_hardship'):
                        p['state'] = 'note'
                        p['reason'] = 'hardship'
                        p['date'] = ''
        elif event in ['paid', 'dispute']:
            if not targets:
                messages.append('Clarify which actual product this concerns.')
                blocked = True
            for p in targets:
                if p.get('state') == 'recorded':
                    messages.append('A recorded promise cannot be changed here; direct changes to the mobile app.')
                    blocked = True
                else:
                    p['state'] = 'note'
                    p['reason'] = event
                    if event == 'paid':
                        messages.append('Explain that payments can take one business day to appear.')
            vars['split_started'] = 'yes'
        elif event in ['refuse', 'too_much']:
            vars['split_started'] = 'yes'
            if not targets:
                messages.append('Clarify which actual product this concerns.')
                blocked = True
            else:
                p = targets[0]
                if p.get('state') == 'recorded':
                    messages.append('A recorded promise cannot be changed here; direct changes to the mobile app.')
                    blocked = True
                elif vars.get('hardship_active') == 'yes':
                    messages.append('Offer connection to support; make no persuasion attempt.')
                    blocked = True
                else:
                    p['state'] = 'open'
                    if event == 'too_much':
                        p['full_too_much'] = True
                    if event == 'too_much' and not p.get('floor_offered'):
                        p['floor_offered'] = True
                        if initial_offer:
                            text = offer(p)
                        else:
                            p['offer_amount'] = p['floor']
                            p['amount'] = p['floor']
                            text = 'Offer the floor of ' + str(p['floor']) + ' for ' + p['label'] + (' on ' + str(p.get('offer_date')) if p.get('offer_date') else '') + ' once. Explain that the rest stays overdue. Obtain agreement; do not ask how much they can pay.'
                    else:
                        p.setdefault('rejected', []).append(signature(p.get('offer_amount', p['past_due']), p.get('offer_date', '')))
                        text = offer(p)
                    if text:
                        messages.append(text)
                        blocked = True
        elif event in ['accept', 'proposal', 'correction']:
            vars['split_started'] = 'yes'
            if not targets:
                messages.append('Clarify which actual product is meant.')
                blocked = True
            if amount_text and len(targets) > 1 and amount_scope != 'per_product':
                messages.append('You proposed an amount for several products. Clarify which product that amount concerns; do not allocate it or copy a combined total to each product.')
                blocked = True
                targets = []
            for p in targets:
                if p.get('state') == 'recorded':
                    messages.append('The promise for ' + p['label'] + ' is already recorded and cannot be changed or cancelled here. Direct changes to the mobile app.')
                    blocked = True
                    continue
                old_date = p.get('date', '')
                p['state'] = 'open'
                p['date'] = ''
                a = float(amount_text) if amount_text else float(p.get('offer_amount', p['past_due']) if event == 'accept' else p.get('amount', p['past_due']))
                if a != a or abs(a) == float('inf'):
                    raise ValueError('Invalid amount')
                amount_invalid = not p['floor'] <= a <= p['past_due']
                amount_message = ''
                if a < p['floor']:
                    if not p.get('floor_offered'):
                        p['floor_offered'] = True
                        amount_message = 'That amount cannot be recorded. Offer ' + str(p['floor']) + ' for ' + p['label'] + ' once and explain that the rest stays overdue; obtain agreement.'
                    else:
                        amount_message = 'The minimum remains ' + str(p['floor']) + '. Clarify the proposed amount without counting it as a refusal or repeating a rejected offer.'
                    p['offer_amount'] = p['floor']
                elif a > p['past_due']:
                    p['offer_amount'] = p['past_due']
                    amount_message = 'Offer the full past-due amount of ' + str(p['past_due']) + ' for ' + p['label'] + ' and obtain agreement; do not silently reduce the proposed amount.'
                else:
                    p['amount'] = a
                    p['offer_amount'] = a
                text_date = phrase
                if not text_date and event == 'accept':
                    text_date = str(p.get('offer_date', ''))
                if not text_date and event == 'correction':
                    text_date = old_date or str(p.get('offer_date', ''))
                if not text_date and old_date:
                    text_date = old_date
                if not text_date:
                    p['offer_date'] = ''
                    if amount_message:
                        messages.append(amount_message)
                    else:
                        messages.append('Ask the exact payment day for ' + p['label'] + '; the proposed amount is ' + str(a) + '.')
                    blocked = True
                    continue
                d = parsed(text_date)
                if not d:
                    p['offer_date'] = ''
                    if amount_message:
                        messages.append(amount_message)
                    vague = bool(re.search(r'\b(week|month|salary|payday)\b|when .*paid', text_date.lower()))
                    if vague:
                        p['vague_count'] = int(p.get('vague_count', 0)) + 1
                        if p['vague_count'] == 1:
                            messages.append('Ask once for the exact payment day for ' + p['label'] + '.')
                        else:
                            p['offer_date'] = p['deadline']
                            messages.append('Propose ' + p['deadline'] + ' for ' + p['label'] + ' and obtain agreement.')
                    else:
                        messages.append('Clarify the exact calendar day for ' + p['label'] + ', asking for a named month or the intended week if necessary. An ambiguous exact date is not a vague-period answer or a refusal.')
                    blocked = True
                    continue
                deadline = datetime.date.fromisoformat(p['deadline'])
                if d < today:
                    p['offer_date'] = ''
                    if amount_message:
                        messages.append(amount_message)
                    messages.append('That date is in the past. Ask for a business day from ' + today.isoformat() + ' through ' + p['deadline'] + '.')
                    blocked = True
                    continue
                adjustment = ''
                date_needs_agreement = False
                if d > deadline:
                    if scope == 'all' and phrase:
                        adjustment = 'The common requested date ' + d.isoformat() + ' exceeds this product deadline; use ' + p['deadline'] + ' and say so in joint read-back.'
                        d = deadline
                    else:
                        d = deadline
                        messages.append('The latest date recordable for ' + p['label'] + ' is ' + p['deadline'] + '. Offer it and obtain agreement.')
                        date_needs_agreement = True
                elif not business(d):
                    d = following(d)
                    if d > deadline:
                        d = deadline
                        messages.append('No later permissible business day fits that proposal. Offer the deadline ' + p['deadline'] + ' and obtain agreement.')
                    else:
                        messages.append('That is a weekend or holiday. Offer ' + d.isoformat() + ' for ' + p['label'] + ' and obtain agreement.')
                    date_needs_agreement = True
                p['offer_date'] = d.isoformat()
                if amount_message:
                    messages.append(amount_message + ' Retain the proposed or explicitly offered payment date ' + p['offer_date'] + ' in this offer.')
                if amount_invalid or date_needs_agreement:
                    blocked = True
                    continue
                p['date'] = d.isoformat()
                p['date_adjustment'] = adjustment
                p['state'] = 'pending'
                if vars.get('hardship_active') == 'yes' and event in ['proposal', 'correction']:
                    p['voluntary_hardship'] = True
        if event != 'confirm' or vars.get('confirmation_state') != 'confirmed':
            if not blocked:
                open_rows = [i for i, p in enumerate(rows) if p.get('state') == 'open']
                while open_rows:
                    current = open_rows[0]
                    vars['current_index'] = current
                    p = rows[current]
                    if vars.get('hardship_active') == 'yes':
                        messages.append('Offer support connection; do not persuade. Voluntary payment proposals remain permitted.')
                        break
                    text = offer(p) if int(p.get('attempts', 0)) == 0 else 'Continue the outstanding offer for ' + p['label'] + ' without repeating a rejected offer.'
                    if text:
                        messages.append(text)
                        break
                    open_rows = [i for i, q in enumerate(rows) if q.get('state') == 'open']
                if not open_rows:
                    pending = [p for p in rows if p.get('state') == 'pending']
                    if pending:
                        vars['confirmation_state'] = 'awaiting'
                        vars['record_mode'] = 'promises'
                        vars['decision_route'] = 'record'
                        messages.append('Read ALL pending products, amounts and dates back together, disclose date adjustments, and ask Do you confirm?')
                    else:
                        vars['decision_route'] = 'reconcile'
        vars['product_state'] = rows
        vars['product_facts'] = json.dumps(rows)
        vars['pending_facts'] = json.dumps([dict(product_id=p['product_id'], label=p['label'], amount=p.get('amount', p.get('past_due', '')), date=p.get('date', ''), adjustment=p.get('date_adjustment', ''), state=p.get('state', '')) for p in rows if p.get('state') in ['pending', 'recorded']])
        vars['next_instruction'] = ' '.join(messages) or 'Continue with the next permitted action.'
except Exception:
    vars['event'] = ''
    vars['resolution_ready'] = 'no'
    vars['close_ready'] = 'no'
    vars['decision_route'] = 'identity' if event in ['callback', 'security'] else 'collect'
    vars['confirmation_state'] = 'none'
    vars['confirmed_promises'] = []
    vars['identity_feedback'] = 'Ask only for the missing or ambiguous detail. Do not submit a partial security answer, count an attempt, schedule a callback or claim success.'
    vars['next_instruction'] = 'The proposed detail could not be validated. Ask for the exact corrected amount or calendar day. Do not write or claim a promise.'

